            "instruction": "You will hear a student veterinary nurse talking about her studies and job on a radio show. For each question, choose the correct answer A, B or C.",
            "audioScript": "Presenter: Welcome back to Campus Radio. Today we're joined by Lee, a student veterinary nurse who is currently combining coursework with practical clinic training. Lee, how do you find managing both work and your studies simultaneously?\n\nLee: Well, honestly, it's very challenging. You're working long, demanding shifts caring for sick animals, and then you have to come home and write detailed medical essays. It really pushes your limits every single day!\n\nPresenter: What advice would you give to teenagers who want to enter this field?\nLee: Many people think they need to find a paid veterinary job immediately, but my strongest advice is to give your time freely as a volunteer at animal rescue shelters. Unpaid work gives you invaluable hands-on experience and shows colleges that you are genuinely dedicated.\n\nPresenter: And how do you feel about the required work placement program?\nLee: The work placement is fantastic because you gain genuine, practical clinical experience while you're still studying theory. You can't learn surgery assistance just from a textbook.\n\nPresenter: Many students study their academic modules online now. How do you find that?\nLee: The flexibility is nice, but studying at a computer alone can feel quite lonely and isolating at times. You miss the spontaneous energy of a bustling lecture hall.\n\nPresenter: So what do you do when you run into a tricky assignment or problem?\nLee: Whenever I get stuck on complex animal pathology questions, I immediately contact fellow students in our WhatsApp study group. Sharing ideas always helps us solve problems faster.\n\nPresenter: And finally, what are your long-term career plans after graduating?\nLee: While most graduates stay in local pet clinics, my dream is to open an exotic pet business specializing in the medical care of reptiles, birds, and unusual rescue wildlife.",
