            "audioScript": "Good afternoon everyone, and welcome to this lecture on the history of the world's most legendary gemstones. Today we look at the extraordinary Hope Diamond. \n\nThis famous jewel is celebrated for its rare, mesmerizing grey-blue color. In terms of dimensions, the diamond measures precisely 25.6 millimetres in length and 21.7 millimetres in width. \n\nIts known historical records begin when a French merchant discovered it in India and sold it to the King of France in the year 1668. It remained in the royal French treasury until the turmoil of the French Revolution, when it was stolen in 1792. \n\nThe jewel later surfaced in Britain, where it was owned by King George IV. After King George died in 1830, the diamond was sold to pay off his massive royal debts. \n\nThe next prominent buyer was a wealthy British banker named Henry Philip Hope, whose family gave the diamond its permanent name. \n\nFollowing many changes of ownership, the diamond was transported to London and then onward to New York, captivating the American public. Today, the Hope Diamond is housed in the Smithsonian Institution in Washington D.C., and insurance experts evaluate its estimated value at approximately a quarter of a billion dollars.",
