            "instruction": "Look at the six sentences for this part. You will hear Mike and Tara talking about a new restaurant/cafe in their area. Decide if each sentence is correct (YES) or incorrect (NO).",
            "audioScript": "Mike: Hey Tara, have you heard about that innovative new pay-per-minute cafe called Ziferblat that just opened down on Market Street?\nTara: Oh, I walked past it yesterday! But as a student on a tight budget, I really don't have much money to spend on eating out right now.\nMike: That's the beauty of it! I find working at my small flat impossible because my flatmates are constantly playing loud music and making noise. So I go to this cafe to get my coursework done.\nTara: But don't you have to pay a steep cover charge when you walk into the cafe?\nMike: Not at all! When you enter through the front door, you don't pay anything upfront. The host simply hands you a little clock with your arrival time written down. The longer you stay, the more you pay—it's three pence per minute, which is very affordable if you only need an hour.\nTara: Really? Do waitresses come around to take orders and serve food to your table?\nMike: No, there are no waitresses. Everything is completely self-service! You can brew unlimited fresh coffee, make tea, and help yourself to cookies and toast from the kitchen counter.\nTara: Sounds popular. Is it always crowded? Don't you struggle to find a seat?\nMike: Not really. The building has three spacious floors with big comfortable sofas and work desks, so there's always plenty of room to sit and study peacefully.\nTara: That sounds amazing, Mike! You've convinced me, let's go there tomorrow afternoon.",
