            "partNumber": 3,
            "title": "Part 3: Questions 11 - 20 (Is Email on its way out? True/False)",
            "instruction": "Look at the sentences below about emails. Read the text and decide if each sentence is correct (A) or incorrect (B).",
            "passageTitle": "Is Email on its way out?",
            "passage": "Whatever anyone says, nothing is going to replace email in the near future, and probably not in the far future. It's almost impossible to use internet technologies without an email address. Many companies, schools and colleges also give all their members a unique email address.\n\nEmail's unbeatable advantage is that either everyone has an email address, or can easily get one. There are obviously nowadays hundreds of different ways to communicate, including Facebook Messenger, Skype, Whatsapp and so on, but not even Facebook with a 1.86 billion monthly active users, has the same reach. Email has an estimated 2.7 billion users, putting it way ahead as the most popular form of online communication.\n\nEmail's second huge advantage is that, unlike Facebook, nobody owns it. Anyone can set up an email service, without paying anyone a fee. The main disadvantage, of course, is that most email is spam, that is email from unknown senders that might be dangerous, which is annoying and time consuming.\n\nEmail's third advantage is that it can be used to share any type of file. You can send documents and photos to your friends, publishers can send you newsletters that look like web pages, airlines can send you PDF files of boarding cards, and so on.\n\nEmail's fourth advantage is that it's a store and forward system. People don't have to be online at the same time to exchange emails, and the emails can be kept for future reference. They can also be forwarded to other people, or printed out.\n\nThere are two simple rules for handling email attachments. First, don't open any attachment that doesn't come from a trusted source, or that you were not expecting. Second, save the attachment and run a virus check before opening it. Better safe than sorry!\n\nNothing can replace email, but you can change the way you use it and make yourself less email-dependent, as it can be annoying when it's used as a messaging system. You can reduce that problem by limiting the times you use it. For example, check email three times a day: before starting work, just before lunch, and before going home. Anybody who is expecting a quick response soon learns they aren't going to get one. Someone who isn't using email for work shouldn't need to check it more than once a day, having a break at weekends. A good alternative is Facebook Messenger, which has become popular because more people are using smartphones to communicate instead of their laptops. It offers flexibility and no spams!",
