            "partNumber": 4,
            "title": "Part 4: Questions 21 - 25 (Snakebite First Aid Multiple Choice)",
            "instruction": "Read the text and questions below. For each question, mark the correct letter A, B, C or D.",
            "passageTitle": "Snakebite First Aid: Myth vs Medical Fact",
            "passage": "You're hiking with a friend. The sun is shining, the birds are singing. Then as you step over a tree log on the path, a snake beneath it leaps out and bites your leg. Out of all the panicky thoughts that race through your mind, one screams the loudest: 'If you get bitten by a snake, suck out the venom.' Terrified, you turn to your friend and tell him to start sucking, but he replies, 'No way! Then we'll both die.'\n\nIs he right? Here's your answer: Most likely, your friend wouldn't die from swallowing snake venom. But if he has an open wound in his mouth, the venom could enter his bloodstream, which is no help to either of you. So, venom-sucking isn't a solution.\n\nTo understand how to treat - and how not to treat - a snake bite, you need to understand how venom affects your body. Note that we don't use the word 'poison' when discussing snakebites. Poisons are toxic, in other words dangerous, if you swallow or smell them. Venoms, on the other hand, are only toxic if they get into soft tissues and the bloodstream. So, technically, if you suck the venom out of a snakebite in your mouth, you won't be affected. But that doesn't mean you should do it! Experts now strongly advise against it.\n\nWhy? Venom enters the bloodstream extremely quickly, and trying to suck it out is ineffective because it's faster than your reaction. The best way to prevent venom from quickly moving through the bloodstream is to remain calm, and avoid doing anything that would increase the heart rate.\n\nBut it's important to note that the chances of receiving a venomous snakebite are very low. Worldwide, there are between 1 and 2 million snakebite incidents per year, resulting in only 50,000 to 100,000 snakebite deaths. So what else should we do? Well, be aware of what snakes are in the place you are walking. That way you will have an idea which ones are dangerous.",
